// zapo's `long` in miniature, with BOTH of its walls in ONE package:
//
//   1. the module body's install step is a forcing `!` --
//      `!function(root, factory){...}(globalRef, factory)`, whose
//      operand's type is `void`, the first byte of every UMD wrapper;
//   2. what the factory installs is a PROTOTYPE, so a consumer that
//      checked-casts an instance needs a [[Get]] that walks.
//
// Neither fix alone makes this package usable, which is the whole reason
// it exists. Fence the bang and `toNumber` is never installed; walk no
// prototype and `toNumber` is invisible -- and BOTH spellings of the
// failure are the same message, `expected function at $.toNumber, got
// undefined`, which is why the two walls hid each other for two blocks.
//
// `>>>0` in the method body is deliberate: it is what the real `long`
// has, and it is what makes the closure infer `() => number` and box
// `func()=>f64`, which the record matcher's exact signature test needs.
"use strict";

function L(lo, hi, u) {
    this.low = 0 | lo;
    this.high = 0 | hi;
    this.unsigned = !!u;
}

!function (n, o) {
    o(L.prototype, "undefined" != typeof n ? "global" : "none");
}("undefined" != typeof globalThis ? globalThis : this, function (p, where) {
    p.toNumber = function () {
        return (this.high >>> 0) * 4294967296 + (this.low >>> 0);
    };
    p.where = where;
});

exports.make = function (lo, hi) { return new L(lo, hi, false) };
